function validate(input) {
  const [{ Days = [] }] = input;
  const seen = new Set();
  for (const [day] of Days) {
    if (day === null) return 'Every row needs a day.';
    const text = String(day);
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
    if (!match) return `${text} is not a date in YYYY-MM-DD form.`;
    const [y, m, d] = [Number(match[1]), Number(match[2]), Number(match[3])];
    const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
    const length = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
    if (y < 1000 || !length || d < 1 || d > length) return `${text} is not a real date.`;
    if (seen.has(text)) return `${text} appears twice in Days.`;
    seen.add(text);
  }
  return null;
}

