function generate(rand, size) {
  const pad = n => String(n).padStart(2, '0');
  const monthLength = (y, m) => [31, (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0 ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
  if (size !== 'small') {
    // Walk forward through the calendar in random steps, so every date is new.
    let y = 1950, m = 1, d = 1;
    const Days = [];
    for (let i = 0; i < 2000; i++) {
      Days.push([`${y}-${pad(m)}-${pad(d)}`]);
      d += 1 + Math.floor(rand() * 20);
      while (d > monthLength(y, m)) { d -= monthLength(y, m); m++; if (m > 12) { m = 1; y++; } }
    }
    return [{ Days }];
  }
  // Hand-picked dates cover single-digit days, month ends, leap days and the turn of a century.
  const special = ['2022-04-12', '2021-08-09', '2020-06-26', '2020-02-29', '2000-01-01', '1999-12-31', '2024-03-01', '2023-11-05', '2010-07-04'];
  const randomDay = () => {
    const y = 1970 + Math.floor(rand() * 60), m = 1 + Math.floor(rand() * 12);
    return `${y}-${pad(m)}-${pad(1 + Math.floor(rand() * monthLength(y, m)))}`;
  };
  const chosen = new Set();
  for (let tries = Math.floor(rand() * 9); tries > 0; tries--) chosen.add(rand() < 0.5 ? special[Math.floor(rand() * special.length)] : randomDay());
  return [{ Days: [...chosen].map(day => [day]) }];
}
